// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1b4f8a', ORANGE = '#e8711a', TEAL = '#118a83', RED = '#ea2027', INK = '#1a1a1a';
  var A = 3, D = 1, P = 1;                // amplitude, midline, period (units of pi)
  var colW = 200;                          // right label column width (px)
  var hotspots = [], cur = null;

  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  container.appendChild(canvas);

  function clamp(lo, v, hi) { return Math.max(lo, Math.min(hi, v)); }
  function cyc() { return Math.PI * P; }
  function fmt(v) { var s = (Math.round(v * 100) / 100).toString(); return s; }

  function piFrac(u) {
    var num = Math.round(u * 8), den = 8;
    if (num === 0) return '0';
    var g = (function gcd(a, b) { return b ? gcd(b, a % b) : a; })(Math.abs(num), den);
    num /= g; den /= g;
    var s = (num === 1 ? 'π' : (num === -1 ? '-π' : num + 'π'));
    return den === 1 ? s : s + '/' + den;
  }

  function bounds() {
    var l = cyc();
    var base = Math.min(D - A, -2), top = Math.max(D + A, 4);
    return {
      xMin: -0.6, xMax: Math.max(4.98, l + 1.85),
      yMin: base - 1.45, yMax: top + 0.85, base: base, top: top
    };
  }

  function curveData() {
    var l = cyc(), n = 241, pts = [];
    for (var i = 0; i < n; i++) {
      var x = l * i / (n - 1);
      pts.push({ x: x, y: D + A * Math.sin(2 * Math.PI * x / l) });
    }
    return pts;
  }

  /* ── drawing helpers ─────────────────────────────────────────────── */
  function head(ctx, x, y, ang, s, color) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-s, s * 0.45); ctx.lineTo(-s, -s * 0.45);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill(); ctx.restore();
  }
  function seg(ctx, x1, y1, x2, y2, color, w, dash) {
    ctx.save(); ctx.beginPath(); ctx.setLineDash(dash || []);
    ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = w; ctx.lineCap = 'butt'; ctx.stroke(); ctx.restore();
  }
  function txt(ctx, s, x, y, color, font, align, base) {
    ctx.save(); ctx.font = font; ctx.textAlign = align || 'left'; ctx.textBaseline = base || 'middle';
    ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(2.5, parseFloat(font) * 0.25);
    ctx.strokeStyle = '#fff'; ctx.strokeText(s, x, y);
    ctx.fillStyle = color; ctx.fillText(s, x, y);
    var w = ctx.measureText(s).width; ctx.restore(); return w;
  }

  function G(chart) {
    var a = chart.chartArea, xs = chart.scales.x, ys = chart.scales.y, b = bounds();
    var S = Math.min(a.width, a.height);
    return {
      a: a, b: b,
      px: function (v) { return xs.getPixelForValue(v); },
      py: function (v) { return ys.getPixelForValue(v); },
      S: S,
      fs: clamp(9, S * 0.055, 15),
      tfs: clamp(8, S * 0.05, 13.5),
      lfs: clamp(8, Math.min(clamp(9, S * 0.055, 15), (colW - 12) / 10.2), 15),
      lw: clamp(1, S * 0.006, 1.6),
      hd: clamp(4.5, S * 0.027, 9),
      l: cyc(),
      colX: a.right + 10
    };
  }

  /* ── background layer: axes + annotation arrows ──────────────────── */
  function drawBack(chart) {
    if (!chart.chartArea) return;
    var g = G(chart), ctx = chart.ctx, a = g.a, px = g.px, py = g.py, b = g.b;
    var plotW = a.right - a.left;

    // x-axis
    var y0 = py(0), x0 = px(0);
    var xEnd = Math.min(px(g.l) + 0.14 * plotW, a.right - 3);
    seg(ctx, a.left, y0, xEnd, y0, INK, g.lw);
    head(ctx, xEnd, y0, 0, g.hd, INK);

    // y-axis
    var yTop = a.top + g.hd + 2, yBot = py(b.base - 0.35);
    seg(ctx, x0, yBot, x0, yTop, INK, g.lw);
    head(ctx, x0, yTop, -Math.PI / 2, g.hd, INK);

    // y ticks
    var k;
    for (k = Math.ceil(b.yMin + 0.4); k <= Math.floor(b.yMax - 0.4); k++) {
      if (k === 0) continue;
      var yy = py(k);
      if (yy < a.top + g.tfs || yy > a.bottom - 2) continue;
      seg(ctx, x0 - 4, yy, x0 + 4, yy, INK, g.lw);
    }
    // x ticks (quarter cycle marks)
    for (k = 1; k <= 4; k++) {
      var xq = px(g.l * k / 4);
      seg(ctx, xq, y0 - 4, xq, y0 + 4, INK, g.lw);
    }

    // midline (orange)
    var mEnd = Math.min(px(g.l) + 0.11 * plotW, a.right - 4);
    var ym = py(D);
    seg(ctx, x0, ym, mEnd - g.hd * 0.6, ym, ORANGE, g.lw * 1.7);
    head(ctx, mEnd, ym, 0, g.hd, ORANGE);

    // amplitude arrow (teal) at quarter cycle
    var xa = px(g.l / 4), yb = py(D), yt = py(D + A);
    seg(ctx, xa, yb, xa, yt + g.hd * 0.6, TEAL, g.lw * 1.6);
    head(ctx, xa, yt, -Math.PI / 2, g.hd, TEAL);
    seg(ctx, xa - 4, yb, xa + 4, yb, TEAL, g.lw * 1.6);

    // period span (red, double headed)
    var lev = py(b.base - 0.8);
    seg(ctx, x0 + g.hd * 0.6, lev, px(g.l) - g.hd * 0.6, lev, RED, g.lw * 1.6);
    head(ctx, x0, lev, Math.PI, g.hd, RED);
    head(ctx, px(g.l), lev, 0, g.hd, RED);
  }

  /* ── foreground layer: all text ──────────────────────────────────── */
  function drawFront(chart) {
    if (!chart.chartArea) return;
    var g = G(chart), ctx = chart.ctx, a = g.a, px = g.px, py = g.py, b = g.b;
    hotspots = [];
    var x0 = px(0), y0 = py(0), lfs = g.lfs;
    var axFont = 'italic bold ' + g.fs.toFixed(1) + 'px Arial, sans-serif';
    var tkFont = g.tfs.toFixed(1) + 'px Arial, sans-serif';
    var lbFont = 'bold ' + lfs.toFixed(1) + 'px Arial, sans-serif';

    // axis names
    txt(ctx, 'y', x0 - g.fs * 0.55, a.top + g.fs * 0.75, INK, axFont, 'right', 'middle');
    txt(ctx, 'x', Math.min(px(g.l) + 0.14 * (a.right - a.left), a.right - 3) + g.fs * 0.55,
      y0 + g.fs * 0.7, INK, axFont, 'left', 'middle');

    // y tick labels
    for (var k = Math.ceil(b.yMin + 0.4); k <= Math.floor(b.yMax - 0.4); k++) {
      if (k === 0) continue;
      var yy = py(k);
      if (yy < a.top + g.tfs || yy > a.bottom - 2) continue;
      txt(ctx, String(k), x0 - 8, yy, INK, tkFont, 'right', 'middle');
    }
    // x tick labels at half and full cycle
    txt(ctx, piFrac(P / 2), px(g.l / 2), y0 + 7, INK, tkFont, 'center', 'top');
    txt(ctx, piFrac(P), px(g.l), y0 + 7, INK, tkFont, 'center', 'top');

    /* equation readout (colour-coded) */
    var bcoef = 2 / P;
    var bStr = (Math.abs(bcoef - 1) < 1e-9) ? '' : fmt(bcoef);
    var parts = [['y = ', '#333'], [fmt(A), TEAL], [' sin(', '#333'], [bStr, RED],
    ['x)', '#333'], [(D < 0 ? ' \u2212 ' : ' + '), '#333'], [fmt(Math.abs(D)), ORANGE]];
    var eqFont = 'bold ' + (lfs * 0.95).toFixed(1) + 'px Arial, sans-serif';
    var eqY = a.top + lfs * 1.0, cx = g.colX, eqW = 0;
    ctx.save(); ctx.font = eqFont;
    for (var i = 0; i < parts.length; i++) {
      var w = txt(ctx, parts[i][0], cx, eqY, parts[i][1], eqFont, 'left', 'middle');
      cx += w; eqW += w;
    }
    ctx.restore();
    hotspots.push({
      x0: g.colX - 4, y0: eqY - lfs, x1: g.colX + eqW + 4, y1: eqY + lfs,
      tip: 'Live equation: y = A sin(bx) + D', title: 'Reading the equation',
      body: 'Every dial appears once in the formula: the teal amplitude A, the red coefficient b = 2\u03c0 / period, and the orange vertical shift D. Read those three numbers off the picture and the equation is complete.'
    });

    /* label column positions */
    var yM = clamp(a.top + lfs * 2.6, py(D), a.bottom - lfs * 0.6);
    var yP = clamp(a.top + lfs, py(b.base - 0.8), a.bottom - lfs * 0.6);
    var yA = clamp(a.top + lfs * 2.8, py(D + A) + lfs * 0.1, a.bottom - lfs);
    if (Math.abs(yA - yM) < lfs * 2.1) yA = Math.max(a.top + lfs * 2.8, yM - lfs * 2.1);
    if (Math.abs(yM - yP) < lfs * 2.1) yM = yP - lfs * 2.1;

    // leader line from amplitude label to the teal arrow
    var tx = px(g.l / 4) + 6, ty = py(D + A * 0.82);
    var sx = g.colX - 8, sy = yA;
    seg(ctx, sx, sy, tx + 7, ty - 5, '#333', Math.max(0.9, g.lw * 0.8));
    head(ctx, tx, ty, Math.atan2(ty - sy, tx - sx), g.hd * 0.8, '#333');

    var wA = txt(ctx, 'Amplitude: |A| = ' + fmt(A), g.colX, yA, TEAL, lbFont, 'left', 'middle');
    var wM = txt(ctx, 'Midline: y = ' + fmt(D), g.colX, yM, ORANGE, lbFont, 'left', 'middle');
    var wP = txt(ctx, 'Period = ' + piFrac(P), g.colX, yP, RED, lbFont, 'left', 'middle');

    var ampBody = 'Amplitude |A| is the vertical distance from the midline up to the peak (and equally down to the trough). It stretches the wave vertically about its centre — the midline never moves and the cycle length never changes.';
    var midBody = 'The midline y = D is the horizontal centre of the wave, the average of the maximum and minimum. Changing D slides the whole curve up or down; the peak-to-midline gap and the period stay the same.';
    var perBody = 'The period is the horizontal length of one complete cycle, here from x = 0 to the red arrowhead. In y = A sin(bx) + D the period equals 2\u03c0/b, so it rescales x only — peak and trough heights are untouched.';

    hotspots.push({ x0: g.colX - 4, y0: yA - lfs, x1: g.colX + wA + 4, y1: yA + lfs, tip: 'Amplitude = distance midline \u2192 peak', title: 'Amplitude |A|', body: ampBody });
    hotspots.push({ x0: px(g.l / 4) - 9, y0: Math.min(py(D), py(D + A)), x1: px(g.l / 4) + 9, y1: Math.max(py(D), py(D + A)), tip: 'Amplitude arrow: ' + fmt(A) + ' units tall', title: 'Amplitude |A|', body: ampBody });
    hotspots.push({ x0: g.colX - 4, y0: yM - lfs, x1: g.colX + wM + 4, y1: yM + lfs, tip: 'Midline: vertical centre of the wave', title: 'Midline y = D', body: midBody });
    hotspots.push({ x0: x0 - 4, y0: py(D) - 6, x1: Math.min(px(g.l) + 0.11 * (a.right - a.left), a.right), y1: py(D) + 6, tip: 'Midline y = ' + fmt(D), title: 'Midline y = D', body: midBody });
    hotspots.push({ x0: g.colX - 4, y0: yP - lfs, x1: g.colX + wP + 4, y1: yP + lfs, tip: 'Period: one full cycle', title: 'Period', body: perBody });
    hotspots.push({ x0: x0 - 4, y0: py(b.base - 0.8) - 7, x1: px(g.l) + 4, y1: py(b.base - 0.8) + 7, tip: 'One cycle spans ' + piFrac(P), title: 'Period', body: perBody });
  }

  var annot = {
    id: 'annot',
    beforeLayout: function (chart) {
      var w = chart.width || 600;
      colW = clamp(112, w * 0.29, 235);
      chart.options.layout.padding = { left: 10, right: colW, top: 14, bottom: 10 };
    },
    beforeDatasetsDraw: function (chart) { drawBack(chart); },
    afterDatasetsDraw: function (chart) { drawFront(chart); }
  };

  var b0 = bounds();
  var chart = new Chart(canvas.getContext('2d'), {
    type: 'scatter',
    data: {
      datasets: [{
        data: curveData(),
        showLine: true,
        pointRadius: 0,
        borderColor: NAVY,
        tension: 0,
        borderCapStyle: 'round',
        borderJoinStyle: 'round',
        borderWidth: function (c) {
