  }

  /* ── interaction handlers ────────────────────────────────────────── */
  window.update_amplitude = function (v) { A = v; refresh(); };
  window.update_midline = function (v) { D = v; refresh(); };
  window.update_period = function (v) { P = v; refresh(); };

  /* ── demo step player ────────────────────────────────────────────── */
  var steps = [
    { title: 'The textbook figure', narration: 'One full cycle of a sine wave centred on the orange line y = 1, reaching up to 4 and down to \u22122, and repeating after a horizontal distance of \u03c0. Three annotations measure three different things.', state: { amplitude: 3, midline: 1, period: 1 } },
    { title: 'Stretch the amplitude', narration: 'Drag the teal arrow: the peak climbs to 5 and the trough drops to \u22123, but the orange midline never moves and the cycle still ends at \u03c0. Amplitude is purely the distance from the centre line to the extreme.', state: { amplitude: 4, midline: 1, period: 1 } },
    { title: 'Shrink the amplitude', narration: 'With a small amplitude the wave hugs the midline. Notice the peak and trough stay symmetric about y = 1 \u2014 the midline is always the average of the maximum and minimum.', state: { amplitude: 1, midline: 1, period: 1 } },
    { title: 'Slide the midline', narration: 'Now push the orange line down to y = \u22121. The entire wave travels with it; the gap from midline to peak is unchanged. Vertical shift relocates the wave, amplitude sizes it.', state: { amplitude: 3, midline: -1, period: 1 } },
    { title: 'Stretch the period', narration: 'Widen the red span to 2\u03c0. The wave needs twice as much horizontal room to finish one cycle, yet the peak and trough heights are untouched \u2014 period is a horizontal, not vertical, measurement.', state: { amplitude: 3, midline: 1, period: 2 } },
    { title: 'Compress the period', narration: 'Squeeze the span to \u03c0/2 and the wave oscillates twice as fast. With midline, amplitude and period all set, you can read the equation y = A sin(2\u03c0x / period) + D straight off the picture.', state: { amplitude: 3, midline: 1, period: 0.5 } }
  ];
  var step = 0;

  function setCtl(id, v) {
    var inp = document.getElementById(id + 'Input'), out = document.getElementById(id + 'Val');
    if (inp) inp.value = v;
    if (out) out.value = v;
  }

  function applyStep(i) {
    step = (i + steps.length) % steps.length;
    var s = steps[step];
    setCtl('amplitude', s.state.amplitude); A = s.state.amplitude;
    setCtl('midline', s.state.midline); D = s.state.midline;
    setCtl('period', s.state.period); P = s.state.period;
    refresh();
    document.getElementById('demoTitle').textContent = s.title;
    document.getElementById('demoNarration').textContent = s.narration;
